import os
from pathlib import Path
from typing import List, Dict, Optional, Tuple
from dataclasses import dataclass
import numpy as np

@dataclass
class VibrationDataRecord:
    machine_id: str
    process_id: str
    label: str                 # "good" or "bad"
    filepath: str

class VibrationDataLoaderPipeline:
    """
    Dedicated pipeline to load and organize vibration dataset files
    with hierarchical folder structure.
    """

    def __init__(self, root_dir: str):
        self.root_dir = Path(root_dir)
        self.data_records: List[VibrationDataRecord] = []
        self.label_encoding = {"good": 0, "bad": 1}

    def scan_dataset(self) -> List[VibrationDataRecord]:
        """
        Walk the directory tree to find CSV vibration files,
        and save metadata as VibrationDataRecords.
        """
        data_records = []

        for root, _, files in os.walk(self.root_dir):
            root_path = Path(root)
            try:
                rel_path = root_path.relative_to(self.root_dir)
                parts = rel_path.parts

                # We expect structures like machine_id/process_id/label/
                if len(parts) == 3:
                    machine_id, process_id, label = parts
                    csv_files = [f for f in files if f.lower().endswith(".csv")]

                    for file in csv_files:
                        record = VibrationDataRecord(
                            machine_id=machine_id,
                            process_id=process_id,
                            label=label,
                            filepath=str(root_path / file)
                        )
                        data_records.append(record)
            except Exception:
                # skip unexpected directory layouts
                continue

        self.data_records = data_records
        return data_records

    def filter_records(self, machines: Optional[List[str]] = None,
                       processes: Optional[List[str]] = None,
                       labels: Optional[List[str]] = None) -> List[VibrationDataRecord]:
        """
        Filter loaded records by criteria.
        """
        filtered = self.data_records

        if machines is not None:
            filtered = [r for r in filtered if r.machine_id in machines]
        if processes is not None:
            filtered = [r for r in filtered if r.process_id in processes]
        if labels is not None:
            filtered = [r for r in filtered if r.label in labels]

        return filtered

    def get_train_test_split(self, test_ratio=0.2, stratify='label', seed=42)\
            -> Tuple[List[VibrationDataRecord], List[VibrationDataRecord]]:
        """
        Create stratified train-test split based on label, machine, or none.
        """
        np.random.seed(seed)

        if stratify == 'label':
            label_groups = {}
            for record in self.data_records:
                label_groups.setdefault(record.label, []).append(record)
            train, test = [], []
            for group in label_groups.values():
                np.random.shuffle(group)
                split_idx = int(len(group)*(1-test_ratio))
                train.extend(group[:split_idx])
                test.extend(group[split_idx:])
        else:
            records = self.data_records.copy()
            np.random.shuffle(records)
            split_idx = int(len(records) * (1 - test_ratio))
            train = records[:split_idx]
            test = records[split_idx:]

        return train, test

