"""# **Preprocessing Pipeline**"""

class SpectrogramPipeline:

    def __init__(self, sampling_rate, window_length, overlap,resize=True):
        self.sampling_rate = sampling_rate
        self.window_length = window_length
        self.overlap = overlap
        self.target_shape = (129,306)  # Height x Width for CNN
        self.resize = resize

    def load_and_preprocess_data(self, csv_filepath):
        """Load CSV data and create spectrograms for all axes"""

        # Load data
        data = pd.read_csv(csv_filepath)

        spectrograms = {}
        axes = ['x', 'y', 'z']

        for axis in axes:
            if axis in data.columns:
                # Preprocess axis data
                axis_data = data[axis].values
                axis_data = axis_data - np.mean(axis_data)  # Remove DC
                axis_data = axis_data / np.std(axis_data)   # Normalize

                # Create spectrogram using STFT
                frequencies, times, Zxx = signal.stft(
                    axis_data,
                    fs=self.sampling_rate,
                    window='hann',
                    nperseg=self.window_length,
                    noverlap=self.overlap
                )

                # Convert to magnitude spectrogram (dB)
                magnitude_spec = 20 * np.log10(np.abs(Zxx) + 1e-10)

                # Zero pad or truncate to fixed time dimension (self.target_shape[1])
                target_time = self.target_shape[1]
                current_time = magnitude_spec.shape[1]

                if current_time < target_time:
                  pad_width = target_time - current_time
                  magnitude_spec = np.pad(magnitude_spec, ((0, 0), (0, pad_width)), mode='constant', constant_values=0)
                else:
                  magnitude_spec = magnitude_spec[:, :target_time]


                # Either keep original OR resize
                if self.resize:
                    from scipy.ndimage import zoom
                    zoom_factors = (
                        self.target_shape[0] / magnitude_spec.shape[0],
                        self.target_shape[1] / magnitude_spec.shape[1]
                    )
                    spec = zoom(magnitude_spec, zoom_factors)
                else:
                    spec = magnitude_spec  # original spectrogram (no resizing)

                # Normalize to [0, 1] for CNN
                spec_min, spec_max = np.min(spec), np.max(spec)
                normalized_spec = (spec - spec_min) / (spec_max - spec_min)

                spectrograms[axis] = normalized_spec

        return spectrograms

import numpy as np
import pandas as pd
from scipy import signal
from scipy.ndimage import zoom

class SpectrogramPipeline2:
    def __init__(self, sampling_rate, window_length, overlap, resize=True,
                 target_shape=(129, 306), dB_clip=(-80.0, 0.0), channel_order=('x','y','z')):
        self.sampling_rate = sampling_rate
        self.window_length = window_length
        self.overlap = overlap
        self.target_shape = target_shape  # (freq_bins=129, time_steps=306)
        self.resize = resize
        self.dB_clip = dB_clip           # clip range for dB spectrograms
        self.channel_order = channel_order
        self.eps = 1e-10

    def _axis_spectrogram(self, axis_data):
        # Remove DC and standardize safely
        axis_data = np.asarray(axis_data, dtype=np.float32)
        axis_data = axis_data - np.mean(axis_data)
        std = np.std(axis_data)
        if std > 0:
            axis_data = axis_data / std

        # STFT -> power spectrogram
        f, t, Zxx = signal.stft(
            axis_data,
            fs=self.sampling_rate,
            window='hann',
            nperseg=self.window_length,
            noverlap=self.overlap,
            boundary=None,
            padded=False
        )
        power = np.abs(Zxx).astype(np.float32) ** 2

        # dB scaling with epsilon and clipping
        spec_db = 10.0 * np.log10(power + self.eps)
        lo, hi = self.dB_clip
        spec_db = np.clip(spec_db, lo, hi)

        # Target time length adjust first (pad/truncate)
        target_T = self.target_shape[1]
        cur_T = spec_db.shape[1]
        if cur_T < target_T:
            pad_total = target_T - cur_T
            pad_left = pad_total // 2
            pad_right = pad_total - pad_left
            spec_db = np.pad(spec_db, ((0, 0), (pad_left, pad_right)), mode='constant', constant_values=lo)
        elif cur_T > target_T:
            start = (cur_T - target_T) // 2
            spec_db = spec_db[:, start:start + target_T]

        # Resize frequency/time grid if needed
        if self.resize:
            zf = (self.target_shape[0] / spec_db.shape[0],
                  self.target_shape[1] / spec_db.shape[1])
            spec_db = zoom(spec_db, zf, order=1)  # bilinear for spectrograms

        # Scale dB to [0,1] using fixed clip range to keep calibration consistent
        spec_01 = (spec_db - lo) / (hi - lo)
        spec_01 = np.clip(spec_01, 0.0, 1.0).astype(np.float32)
        return spec_01  # (F, T)

    def load_and_preprocess_data(self, csv_filepath):
        data = pd.read_csv(csv_filepath)

        spectrograms = {}
        for axis in ('x', 'y', 'z'):
            if axis in data.columns:
                spec = self._axis_spectrogram(data[axis].values)
                # Final safety: enforce target shape
                if spec.shape != self.target_shape:
                    # If STFT params produce 130 bins, crop/resize one row
                    spec = zoom(spec, (self.target_shape[0] / spec.shape[0],
                                       self.target_shape[1] / spec.shape[1]), order=1).astype(np.float32)
                spectrograms[axis] = spec

        return spectrograms  # dict of axis -> (129, 306)

    def stack_for_model(self, spectrograms_dict):
        # Build (129, 306, 3) in channel_order; if an axis is missing, fill zeros
        h, w = self.target_shape
        chans = []
        for axis in self.channel_order:
            if axis in spectrograms_dict:
                chans.append(spectrograms_dict[axis])
            else:
                chans.append(np.zeros((h, w), dtype=np.float32))
        spec_hwc = np.stack(chans, axis=-1).astype(np.float32)  # (H, W, 3)
        return spec_hwc

