"""# **Creating Spectrogram**"""

def create_spectrograms_and_labels(records, spectrogram_loader, label_mapping={"good": 0, "bad": 1}):

    processed_spectrograms = []
    labels = []

    for record in records:
        # Load and preprocess spectrograms dict: {'x': ..., 'y': ..., 'z': ...}
        spectrograms = spectrogram_loader(record.filepath)

        # Stack axis spectrograms into shape (freq_bins, time_steps, 3)
        spec_stack = np.stack([spectrograms[axis] for axis in ['x', 'y', 'z']], axis=-1)

        processed_spectrograms.append(spec_stack)
        labels.append(label_mapping[record.label])

    # Convert lists to arrays
    processed_spectrograms_array = np.array(processed_spectrograms)
    labels_array = np.array(labels)

    return processed_spectrograms_array, labels_array

