"""# **Model Building(CNN)**"""

import tensorflow as tf
from tensorflow.keras import layers, models, metrics
from tensorflow.keras.callbacks import ModelCheckpoint, EarlyStopping

#model designed for time series
def create_cnn_model(input_shape=(129, 306, 3), num_classes=2):
    model = models.Sequential()

    # Conv Block 1
    model.add(layers.Conv2D(32, (3,3), activation='relu', padding='same', input_shape=input_shape))
    model.add(layers.BatchNormalization())
    model.add(layers.MaxPooling2D((2,2)))
    model.add(layers.Dropout(0.25))

    # Conv Block 2
    model.add(layers.Conv2D(64, (3,3), activation='relu', padding='same'))
    model.add(layers.BatchNormalization())
    model.add(layers.MaxPooling2D((2,2)))
    model.add(layers.Dropout(0.25))

    # Conv Block 3
    model.add(layers.Conv2D(128, (3,3), activation='relu', padding='same'))
    model.add(layers.BatchNormalization())
    model.add(layers.MaxPooling2D((2,2)))
    model.add(layers.Dropout(0.25))

    # Global Average Pooling
    model.add(layers.GlobalAveragePooling2D())

    # Dense Layers
    model.add(layers.Dense(512, activation='relu'))
    model.add(layers.Dropout(0.5))
    model.add(layers.Dense(256, activation='relu'))
    model.add(layers.Dropout(0.5))

    # Output Layer
    model.add(layers.Dense(1, activation='sigmoid'))

    return model

"""# **Compile with Adams**"""

def compile_with_adam(model, lr=1e-3):
    model.compile(
        optimizer=tf.keras.optimizers.Adam(learning_rate=lr),
        loss=tf.keras.losses.BinaryCrossentropy(from_logits=False),
        metrics=[
            'accuracy',
            tf.keras.metrics.Precision(name='precision'),
            tf.keras.metrics.Recall(name='recall'),
            tf.keras.metrics.AUC(name='roc_auc', curve='ROC', num_thresholds=1000, summation_method='interpolation'),
            tf.keras.metrics.AUC(name='pr_auc', curve='PR', num_thresholds=1000, summation_method='interpolation'),
        ],
    )
    return model

"""# **Compile with SGD**"""

def compile_with_sgd(model, lr=1e-2, momentum=0.9, nesterov=True):
    model.compile(
        optimizer=tf.keras.optimizers.SGD(learning_rate=lr, momentum=momentum, nesterov=nesterov),
        loss=tf.keras.losses.BinaryCrossentropy(from_logits=False),
        metrics=[
            'accuracy',
            tf.keras.metrics.Precision(name='precision'),
            tf.keras.metrics.Recall(name='recall'),
            tf.keras.metrics.AUC(name='roc_auc', curve='ROC', num_thresholds=1000, summation_method='interpolation'),
            tf.keras.metrics.AUC(name='pr_auc', curve='PR', num_thresholds=1000, summation_method='interpolation'),
        ],
    )
    return model

"""# **Training Utility**"""

def train_and_log(model_builder, compiler, train_data, val_data, run_name, epochs=50, patience=8):
    os.makedirs('runs', exist_ok=True)
    ckpt_path = f"runs/{run_name}_best.keras"
    log_path = f"runs/{run_name}.csv"

    callbacks = [
        EarlyStopping(monitor='val_pr_auc', mode='max', patience=patience, restore_best_weights=True, verbose=1),
        ModelCheckpoint(ckpt_path, monitor='val_pr_auc', mode='max', save_best_only=True, verbose=1),
        CSVLogger(log_path)
    ]

    model = model_builder()
    model = compiler(model)

    history = model.fit(
        train_data,
        validation_data=val_data,
        epochs=epochs,
        callbacks=callbacks,
        verbose=1
    )
    return model, history.history, ckpt_path, log_path

