import matplotlib.pyplot as plt

def plot_histories_side_by_side(adam_history, sgd_history, metrics=('loss','accuracy','precision','recall','roc_auc','pr_auc')):
    a = adam_history.history
    s = sgd_history.history
    # Determine the minimum number of epochs completed by either model
    min_epochs = min(len(a.get('loss', [])), len(s.get('loss', [])))
    epochs = range(1, min_epochs + 1)

    n = len(metrics)
    plt.figure(figsize=(6 * 2, 3.2 * n))  # 2 columns: train and val per metric

    for i, m in enumerate(metrics):
        # Training curves
        plt.subplot(n, 2, 2*i + 1)
        if m in a:
            plt.plot(epochs, a[m][:min_epochs], label='Adam', linewidth=2)
        if m in s:
            plt.plot(epochs, s[m][:min_epochs], label='SGD', linewidth=2)
        plt.title(f'Train {m}')
        plt.xlabel('Epoch')
        plt.ylabel(m)
        plt.grid(True, alpha=0.3)
        plt.legend()

        # Validation curves
        plt.subplot(n, 2, 2*i + 2)
        if f'val_{m}' in a:
            plt.plot(epochs, a[f'val_{m}'][:min_epochs], label='Adam', linewidth=2)
        if f'val_{m}' in s:
            plt.plot(epochs, s[f'val_{m}'][:min_epochs], label='SGD', linewidth=2)
        plt.title(f'Val {m}')
        plt.xlabel('Epoch')
        plt.ylabel(m)
        plt.grid(True, alpha=0.3)
        plt.legend()

    plt.tight_layout()
    plt.show()

