"""# **Hyperparameter Tuning**

# **Adams Tunning**
"""

import tensorflow as tf
import keras_tuner as kt
from tensorflow.keras import layers, models, regularizers

def build_adam_model(hp, input_shape=(129, 306, 3), num_classes=2):
    # Architecture knobs
    n_blocks    = hp.Int("conv_blocks", 1, 5, step=1)
    ksize       = hp.Int("kernel_size", 1, 5, step=1)
    pool_type   = hp.Choice("pooling", ["max", "avg"])
    use_dropout = hp.Boolean("use_dropout")
    wd          = hp.Choice("weight_decay", [0.0, 1e-5, 5e-5, 1e-4])

    m = models.Sequential(name="adam_bayes_prauc")
    m.add(layers.Input(shape=input_shape))

    for i in range(1, n_blocks + 1):
        filters = hp.Int(f"filters_{i}", 32, 128, step=4)
        m.add(layers.Conv2D(filters, (ksize, ksize), padding="same",
                            activation="relu",
                            kernel_regularizer=regularizers.l2(wd) if wd>0 else None))
        m.add(layers.BatchNormalization())
        if pool_type == "max":
            m.add(layers.MaxPooling2D((2, 2)))
        else:
            m.add(layers.AveragePooling2D((2, 2)))
        if use_dropout:
            m.add(layers.Dropout(rate=hp.Float(f"dropout_{i}", 0.1, 0.6, step=0.1)))

    m.add(layers.GlobalAveragePooling2D())
    m.add(layers.Dense(64, activation="relu",
                       kernel_regularizer=regularizers.l2(wd) if wd>0 else None))
    if use_dropout:
        m.add(layers.Dropout(rate=hp.Float("dropout_head", 0.1, 0.6, step=0.1)))
    m.add(layers.Dense(1, activation="sigmoid"))

    # Adam hyperparameters
    adam_lr      = hp.Float("adam_lr", 1e-5, 3e-3, sampling="log")
    adam_beta1   = hp.Float("adam_beta1", 0.85, 0.99, step=0.01)
    adam_beta2   = hp.Float("adam_beta2", 0.90, 0.999, step=0.01)
    adam_eps     = hp.Choice("adam_epsilon", [1e-7, 1e-8])

    opt = tf.keras.optimizers.Adam(
        learning_rate=adam_lr, beta_1=adam_beta1, beta_2=adam_beta2, epsilon=adam_eps
    )

    m.compile(
        optimizer=opt,
        loss=tf.keras.losses.BinaryCrossentropy(),
        metrics=[
            "accuracy",
            tf.keras.metrics.Precision(name="precision"),
            tf.keras.metrics.Recall(name="recall"),
            tf.keras.metrics.AUC(name="roc_auc", curve="ROC"),
            tf.keras.metrics.AUC(name="pr_auc",  curve="PR"),
        ],
    )
    return m

tuner = kt.BayesianOptimization(
    hypermodel=build_adam_model,
    objective=kt.Objective("val_pr_auc", direction="max"),
    max_trials=15,
    num_initial_points=12,
    seed=42,
    directory="optimization",
    project_name="cnn_adam_bayes_prauc",
    overwrite=True,
)

early = tf.keras.callbacks.EarlyStopping(
    monitor="val_pr_auc", mode="max", patience=8, restore_best_weights=True
)
checkpoint = tf.keras.callbacks.ModelCheckpoint(
    "best_adam_bayes.keras", monitor="val_pr_auc", mode="max", save_best_only=True
)

def get_batch_size(hp):
    return hp.Choice("batch_size", values=[16, 32, 64, 128])

tuner.search(
    x=X_train, y=y_train,
    epochs=20,
    validation_data=(X_val, y_val),
    batch_size=get_batch_size(tuner.oracle.hyperparameters),
    callbacks=[early, checkpoint],
    class_weight=class_weight_dict_clean,
    verbose=1
)

best_hp = tuner.get_best_hyperparameters(1)[0]
print("Best hyperparameters:")
for k, v in best_hp.values.items():
    print(f"{k}: {v}")

best_model = tuner.hypermodel.build(best_hp)
best_model.summary()

# Optional brief retrain on train+val
final_hist = best_model.fit(
    np.concatenate([X_train, X_val]), np.concatenate([y_train, y_val]),
    epochs=30,
    validation_split=0.05,
    callbacks=[early],
    class_weight=class_weight_dict_clean,
    verbose=1
)

test_results = best_model.evaluate(test_spectrograms_array, test_labels_array, verbose=1)
print(dict(zip(best_model.metrics_names, test_results)))

# Manual AUC-PR calculation
from sklearn.metrics import precision_recall_curve, auc

y_pred_probs = best_model.predict(test_spectrograms_array)[:, 0]  # sigmoid output
precision, recall, _ = precision_recall_curve(test_labels_array, y_pred_probs)
auc_pr = auc(recall, precision)
print(f"Manual Test AUC-PR for tunned_adam model: {auc_pr:.4f}")

"""# **SGD Tunning**"""

import tensorflow as tf
import keras_tuner as kt
from tensorflow.keras import layers, models, regularizers

def build_sgd_model(hp, input_shape=(129, 306, 3), num_classes=2):
    # Architecture knobs you requested
    n_blocks   = hp.Int("conv_blocks", 1, 5, step=1)
    ksize      = hp.Int("kernel_size", 1, 5, step=1)
    pool_type  = hp.Choice("pooling", ["max", "avg"])
    use_dropout= hp.Boolean("use_dropout")
    # Filters per block (shared step=4)
    # Per-block filters allow smaller/larger stacks while keeping bounds
    filters = [hp.Int(f"filters_{i}", 32, 128, step=4) for i in range(1, n_blocks+1)]

    # Regularization
    wd = hp.Choice("weight_decay", [0.0, 1e-5, 5e-5, 1e-4])

    m = models.Sequential(name="sgd_bayes_prauc")
    m.add(layers.Input(shape=input_shape))

    for i in range(n_blocks):
        m.add(layers.Conv2D(filters[i], (ksize, ksize), padding="same",
                            activation="relu",
                            kernel_regularizer=regularizers.l2(wd) if wd>0 else None))
        m.add(layers.BatchNormalization())
        if pool_type == "max":
            m.add(layers.MaxPooling2D((2,2)))
        else:
            m.add(layers.AveragePooling2D((2,2)))
        if use_dropout:
            m.add(layers.Dropout(rate=hp.Float(f"dropout_{i+1}", 0.1, 0.6, step=0.1)))

    m.add(layers.GlobalAveragePooling2D())
    # Small head to limit params
    m.add(layers.Dense(64, activation="relu",
                       kernel_regularizer=regularizers.l2(wd) if wd>0 else None))
    if use_dropout:
        m.add(layers.Dropout(rate=hp.Float("dropout_head", 0.1, 0.6, step=0.1)))
    m.add(layers.Dense(1, activation="sigmoid"))

    # SGD hyperparameters to tune
    lr       = hp.Float("sgd_lr", 5e-4, 2e-2, sampling="log")
    momentum = hp.Float("sgd_momentum", 0.0, 0.95, step=0.05)
    nesterov = hp.Boolean("sgd_nesterov")

    opt = tf.keras.optimizers.SGD(learning_rate=lr, momentum=momentum, nesterov=nesterov)

    m.compile(
        optimizer=opt,
        loss=tf.keras.losses.BinaryCrossentropy(),
        metrics=[
            "accuracy",
            tf.keras.metrics.Precision(name="precision"),
            tf.keras.metrics.Recall(name="recall"),
            tf.keras.metrics.AUC(name="roc_auc", curve="ROC"),
            tf.keras.metrics.AUC(name="pr_auc",  curve="PR"),
        ],
    )
    return m

tuner = kt.BayesianOptimization(
    hypermodel=build_sgd_model,
    objective=kt.Objective("val_pr_auc", direction="max"),
    max_trials=15,
    num_initial_points=12,
    seed=42,
    directory="optimization",
    project_name="cnn_sgd_bayes_prauc",
    overwrite=True,
)

early = tf.keras.callbacks.EarlyStopping(
    monitor="val_pr_auc", mode="max", patience=8, restore_best_weights=True
)
checkpoint = tf.keras.callbacks.ModelCheckpoint(
    "best_sgd_bayes.keras", monitor="val_pr_auc", mode="max", save_best_only=True
)

def get_batch_size(hp):
    return hp.Choice("batch_size", values=[16, 32, 64, 128])

tuner.search(
    x=X_train, y=y_train,
    epochs=20,
    validation_data=(X_val, y_val),
    batch_size=get_batch_size(tuner.oracle.hyperparameters),
    callbacks=[early, checkpoint],
    class_weight=class_weight_dict_clean,
    verbose=1
)

best_hp_sgd = tuner.get_best_hyperparameters(1)[0]
print("Best hyperparameters:")
for k,v in best_hp_sgd.values.items():
    print(f"{k}: {v}")

best_model_sgd = tuner.hypermodel.build(best_hp)
best_model_sgd.summary()

# Optional: retrain on train+val with a small internal split for stability
final_hist = best_model_sgd.fit(
    np.concatenate([X_train, X_val]), np.concatenate([y_train, y_val]),
    epochs=30,
    validation_split=0.05,
    callbacks=[early],
    class_weight=class_weight_dict_clean,
    verbose=1
)

print(dict(zip(best_model.metrics_names, best_model.evaluate(test_spectrograms_array, test_labels_array, verbose=0))))

# Manual AUC-PR calculation
